"""Merge the classic ESP32 4 MB serial-flash image, using built artifacts."""
import json
import pathlib
import subprocess
import sys

build = pathlib.Path('.pio/build/esp32dev')
version = json.loads(pathlib.Path('package.json').read_text())['version']
output = pathlib.Path('build_output/release') / f'WLED_{version}_ESP32_factory.bin'
boot_app = list((pathlib.Path.home() / '.platformio/packages').rglob('boot_app0.bin'))
if not boot_app:
    raise FileNotFoundError('boot_app0.bin not found in installed PlatformIO packages')
subprocess.run([
    sys.executable, '-m', 'esptool', '--chip', 'esp32', 'merge-bin',
    '--output', str(output), '--flash-mode', 'dio', '--flash-freq', '40m',
    '--flash-size', '4MB',
    '0x1000', str(build / 'bootloader.bin'),
    '0x8000', str(build / 'partitions.bin'),
    '0xe000', str(boot_app[0]),
    '0x10000', str(build / 'firmware.bin'),
], check=True)
